package dev.seaglass.core

import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.sqrt

/**
 * 2D Signed Distance Field (SDF) primitive, smooth-minimum (`smin`) coalescing,
 * and analytical bevel normal evaluator for SeaGlass.
 *
 * All functions in [SeaGlassSdfEngine] have exact 1:1 mathematical parity with
 * the GPU shader dialects (Vulkan GLSL 450, OpenGL ES 3.00, and Android AGSL)
 * generated by [dev.seaglass.core.backend.SeaGlassShaderCompiler].
 */
object SeaGlassSdfEngine {

    /**
     * Maximum number of coalescing SDF nodes evaluated per local cluster in a single GPU pass.
     * Kept at 4 so every node fits in a single 256-byte `std140` uniform block across
     * Vulkan, OpenGL ES 3.0, and AGSL without spilling mobile GPU registers.
     */
    const val MAX_SDF_NODES = 4

    /**
     * Single 2D expressive shape node in pixel coordinates relative to the render target origin.
     *
     * @property centerX Horizontal center in pixels.
     * @property centerY Vertical center in pixels.
     * @property halfWidth Half-width in pixels (`width / 2f`).
     * @property halfHeight Half-height in pixels (`height / 2f`).
     * @property cornerTopRight Top-right corner radius in pixels.
     * @property cornerBottomRight Bottom-right corner radius in pixels.
     * @property cornerBottomLeft Bottom-left corner radius in pixels.
     * @property cornerTopLeft Top-left corner radius in pixels.
     * @property cornerSmoothing Superellipse exponent (`2.0f` = circle arc, `2.5f` = M3 Expressive squircle).
     * @property tintColorArgb Packed ARGB tint of this node.
     * @property thicknessPx Physical slab thickness in pixels.
     */
    data class SdfNode(
        val centerX: Float,
        val centerY: Float,
        val halfWidth: Float,
        val halfHeight: Float,
        val cornerTopRight: Float,
        val cornerBottomRight: Float,
        val cornerBottomLeft: Float,
        val cornerTopLeft: Float,
        val cornerSmoothing: Float = 2.45f,
        val tintColorArgb: Int = 0xFF6EE7C8.toInt(),
        val thicknessPx: Float = 28f,
        val startShapeKind: SeaGlassShapeKind? = null,
        val endShapeKind: SeaGlassShapeKind? = null,
        val shapeMorphProgress: Float = 0f
    ) {
        constructor(
            centerX: Float,
            centerY: Float,
            halfWidth: Float,
            halfHeight: Float,
            uniformCornerRadius: Float,
            cornerSmoothing: Float = 2.45f,
            tintColorArgb: Int = 0xFF6EE7C8.toInt(),
            thicknessPx: Float = 28f,
            startShapeKind: SeaGlassShapeKind? = null,
            endShapeKind: SeaGlassShapeKind? = null,
            shapeMorphProgress: Float = 0f
        ) : this(
            centerX = centerX,
            centerY = centerY,
            halfWidth = halfWidth,
            halfHeight = halfHeight,
            cornerTopRight = uniformCornerRadius,
            cornerBottomRight = uniformCornerRadius,
            cornerBottomLeft = uniformCornerRadius,
            cornerTopLeft = uniformCornerRadius,
            cornerSmoothing = cornerSmoothing,
            tintColorArgb = tintColorArgb,
            thicknessPx = thicknessPx,
            startShapeKind = startShapeKind,
            endShapeKind = endShapeKind,
            shapeMorphProgress = shapeMorphProgress
        )
    }

    /**
     * Result of evaluating a multi-node coalescing SDF scene at a 2D pixel coordinate `(px, py)`.
     */
    data class SdfEvaluation(
        val signedDistancePx: Float,
        val gradX: Float,
        val gradY: Float,
        val edgeBevelFactor: Float,
        val normalX: Float,
        val normalY: Float,
        val normalZ: Float,
        val blendedTintArgb: Int,
        val blendedThicknessPx: Float
    ) {
        val isInside: Boolean get() = signedDistancePx <= 0f
    }

    /**
     * Evaluates the signed distance from `(px, py)` to an expressive rounded box / squircle [node].
     * Negative values are inside the shape, zero is on the boundary, positive values are outside.
     */
    fun evaluateNodeSdf(px: Float, py: Float, node: SdfNode): Float {
        val dx = px - node.centerX
        val dy = py - node.centerY

        // If this node carries a Material 3 Expressive polygon shape (or active shape morph),
        // evaluate its polar star-shaped distance field so Cookie/Clover/Flower/Heart shapes
        // can coalesce via sminCubic liquid bridges while morphing their lobes!
        val sKind = node.startShapeKind
        if (sKind != null) {
            val eKind = node.endShapeKind ?: sKind
            val angle = kotlin.math.atan2(dy, dx)
            val polarScale = SeaGlassShapeMorph.evaluatePolarRadiusScale(
                startKind = sKind,
                endKind = eKind,
                progress = node.shapeMorphProgress,
                angleRad = angle
            )
            val rx = (node.halfWidth * polarScale).coerceAtLeast(2f)
            val ry = (node.halfHeight * polarScale).coerceAtLeast(2f)
            val nx = dx / rx
            val ny = dy / ry
            val normDist = sqrt(nx * nx + ny * ny)
            val avgR = min(rx, ry)
            return (normDist - 1f) * avgR
        }

        // Select quadrant corner radius: (dx > 0, dy > 0) = bottom-right in screen Y-down coords
        val rRight = if (dy > 0f) node.cornerBottomRight else node.cornerTopRight
        val rLeft = if (dy > 0f) node.cornerBottomLeft else node.cornerTopLeft
        val rawRadius = if (dx > 0f) rRight else rLeft
        val maxRadius = (min(node.halfWidth, node.halfHeight) * 1.65f).coerceAtLeast(0f)
        val r = rawRadius.coerceIn(0f, maxRadius)

        val qx = abs(dx) - node.halfWidth + r
        val qy = abs(dy) - node.halfHeight + r

        val outsideX = max(qx, 0f)
        val outsideY = max(qy, 0f)
        val insideDist = min(max(qx, qy), 0f)

        // True Euclidean L2 exterior distance ensures |grad(d)| == 1 everywhere outside the shape
        // so sminCubic coalescing bridges form pure isotropic hourglass necks without 45-degree lobes.
        val cornerNorm = sqrt(outsideX * outsideX + outsideY * outsideY)

        return insideDist + cornerNorm - r
    }

    /**
     * Inigo Quilez's $C^2$-continuous cubic polynomial smooth minimum (`smin`).
     * Smoothly coalesces two signed distances [da] and [db] over a bridge radius [k] > 0.
     */
    fun sminCubic(da: Float, db: Float, k: Float): Float {
        if (k <= 0.0001f) return min(da, db)
        val h = max(k - abs(da - db), 0f) / k
        return min(da, db) - h * h * h * k * (1f / 6f)
    }

    /**
     * Computes the smooth material interpolation weight in `[0f..1f]` when coalescing
     * field [da] (weight 0) and field [db] (weight 1) with smoothness radius [k].
     */
    fun sminBlendWeight(da: Float, db: Float, k: Float): Float {
        if (k <= 0.0001f) return if (da <= db) 0f else 1f
        val h = (max(k - abs(da - db), 0f) / k).coerceIn(0f, 1f)
        val m = h * h * 0.5f
        return if (da < db) m else 1f - m
    }

    /**
     * Evaluates a multi-node coalescing scene at `(px, py)` including analytical gradient,
     * tumbled edge bevel normal, and Oklab-blended tint across coalescing droplets.
     */
    fun evaluateScene(
        px: Float,
        py: Float,
        nodes: List<SdfNode>,
        smoothRadiusPx: Float,
        bevelWidthPx: Float = 24f
    ): SdfEvaluation {
        require(nodes.isNotEmpty()) { "nodes must not be empty" }
        val count = min(nodes.size, MAX_SDF_NODES)

        var combinedDist = evaluateNodeSdf(px, py, nodes[0])
        var blendedTint = nodes[0].tintColorArgb
        var blendedThickness = nodes[0].thicknessPx

        for (i in 1 until count) {
            val node = nodes[i]
            val dNode = evaluateNodeSdf(px, py, node)
            val weight = sminBlendWeight(combinedDist, dNode, smoothRadiusPx)
            combinedDist = sminCubic(combinedDist, dNode, smoothRadiusPx)
            if (weight > 0.001f) {
                blendedTint = SeaGlassColorMath.lerpOklab(blendedTint, node.tintColorArgb, weight)
                blendedThickness += (node.thicknessPx - blendedThickness) * weight
            }
        }

        // Central finite difference for 2D SDF gradient (matches GPU shader step eps = 0.75px)
        val eps = 0.75f
        var distXPlus = evaluateNodeSdf(px + eps, py, nodes[0])
        var distXMinus = evaluateNodeSdf(px - eps, py, nodes[0])
        var distYPlus = evaluateNodeSdf(px, py + eps, nodes[0])
        var distYMinus = evaluateNodeSdf(px, py - eps, nodes[0])

        for (i in 1 until count) {
            val node = nodes[i]
            distXPlus = sminCubic(distXPlus, evaluateNodeSdf(px + eps, py, node), smoothRadiusPx)
            distXMinus = sminCubic(distXMinus, evaluateNodeSdf(px - eps, py, node), smoothRadiusPx)
            distYPlus = sminCubic(distYPlus, evaluateNodeSdf(px, py + eps, node), smoothRadiusPx)
            distYMinus = sminCubic(distYMinus, evaluateNodeSdf(px, py - eps, node), smoothRadiusPx)
        }

        val rawGx = (distXPlus - distXMinus) / (2f * eps)
        val rawGy = (distYPlus - distYMinus) / (2f * eps)
        val gradLen = sqrt(rawGx * rawGx + rawGy * rawGy).coerceAtLeast(1e-4f)
        val gx = rawGx / gradLen
        val gy = rawGy / gradLen

        // Tumbled bevel factor tau in [0f..1f]: 1 at boundary (d = 0), 0 deep in interior (d <= -bevelWidthPx)
        val safeBevel = max(2f, bevelWidthPx)
        val interiorDepth = ((-combinedDist) / safeBevel).coerceIn(0f, 1f)
        val smoothStep = interiorDepth * interiorDepth * (3f - 2f * interiorDepth)
        val tau = 1f - smoothStep

        // Reconstruct 3D outward surface normal of the tumbled sea-glass dome
        val nxRaw = gx * tau * 0.85f
        val nyRaw = gy * tau * 0.85f
        val nzRaw = sqrt(max(0.06f, 1f - tau * tau))
        val nLen = sqrt(nxRaw * nxRaw + nyRaw * nyRaw + nzRaw * nzRaw).coerceAtLeast(1e-4f)

        return SdfEvaluation(
            signedDistancePx = combinedDist,
            gradX = gx,
            gradY = gy,
            edgeBevelFactor = tau,
            normalX = nxRaw / nLen,
            normalY = nyRaw / nLen,
            normalZ = nzRaw / nLen,
            blendedTintArgb = blendedTint,
            blendedThicknessPx = blendedThickness
        )
    }
}
